parameters.inputSchema:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "type": "object",
  "properties": {
    "template": {
      "type": "string",
      "description": "The fully reconstructed transcript text, where all specific niche keywords, data, or tools must be replaced with fill-in-the-blank tokens formatted exactly like [[ description ]]."
    },
    "stage": {
      "type": "string",
      "enum": ["TOFU", "MOFU", "BOFU"],
      "description": "The marketing funnel stage of the script. TOFU=Broad/Hacks/Easy. MOFU=Niche trust/Storytelling. BOFU=Hyper-educational/Deep tutorial."
    },
    "cta": {
      "type": "string",
      "enum": ["Follow", "Freebie", "Offer"],
      "description": "The type of call to action used at the end of the script. Follow=Profile growth prompt. Freebie=Keyword command for lead magnet. Offer=Paid service/product pitching."
    },
    "type": {
      "type": "string",
      "enum": ["Simple", "Complex"],
      "description": "The structural complexity rating of the script. Simple=Straight line list/tip. Complex=Multi-perspective/Dialogue/Comparative frameworks."
    },
    "perspective": {
      "type": "string",
      "enum": ["Educational", "Storytelling"],
      "description": "The delivery style or narrative angle of the script. Educational=Direct teaching/talking head. Storytelling=Narrative delivery, case studies, or anecdotes."
    }
  },
  "required": ["template", "stage", "cta", "type", "perspective"],
  "additionalProperties": false
}

parameters.jsonBody:
={{ {
  "children": (() => {
    const template = $('Code in JavaScript').item.json.template || "";
    const richText = [];

    const chunks = template.match(/[\s\S]{1,2000}/g) || [];
    chunks.forEach(chunk => {
      richText.push({
        "type": "text",
        "text": { "content": chunk }
      });
    });

    return [
      {
        "object": "block",
        "type": "code",
        "code": {
          "rich_text": richText,
          "language": "plain text"
        }
      }
    ];
  })()
} }}

parameters.jsCode:
const llmOutput = $input.item.json.output;

let templateText = llmOutput.template || "";

templateText = templateText.replace(/\[\[\s*(.*?)\s*\]\]/g, "{{ $1 }}");

const sentenceEndRegex = /((?<!\b[a-zA-Z]\.[a-zA-Z])(?<!\b(?:eg|ie|etc|vs|ca|dr|mr|mrs|ms|st|al|am|pm|co|corp|inc|approx|dept|univ|vol|ed))\.|[?!]+|\.\.\.|\…)\s+/gi;

const matches = templateText.match(sentenceEndRegex) || [];
let processedTemplate = templateText;

if (matches.length > 1) {
    processedTemplate = templateText.replace(sentenceEndRegex, (match, p1) => {
        return p1 + "\n\n";
    });
}

let pageTitle = "Template";
const firstMatch = templateText.match(sentenceEndRegex);

if (firstMatch) {
    const firstPunctuationIndex = templateText.indexOf(firstMatch[0]) + firstMatch[0].trim().length;
    pageTitle = templateText.substring(0, firstPunctuationIndex).trim();
} else {
    pageTitle = templateText.trim();
}

pageTitle = pageTitle.replace(/\r?\n|\r/g, " ");

return {
    json: {
        title: pageTitle,
        template: processedTemplate.trim(),
        stage: llmOutput.stage,
        cta: llmOutput.cta,
        type: llmOutput.type,
        perspective: llmOutput.perspective
    }
};

